import sys, json, re, math, zipfile, threading, time
import xml.etree.ElementTree as ET
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP, ROUND_DOWN, ROUND_UP

M = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
R_ID = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"


class Err:
    __slots__ = ('c',)

    def __init__(self, c):
        self.c = c

    def __repr__(self):
        return self.c


E_DIV = Err('#DIV/0!')
E_VAL = Err('#VALUE!')
E_NA = Err('#N/A')
E_NUM = Err('#NUM!')
E_REF = Err('#REF!')
E_NAME = Err('#NAME?')
E_NULL = Err('#NULL!')
E_CIRC = Err('#VALUE!')
ERRMAP = {e.c: e for e in (E_DIV, E_VAL, E_NA, E_NUM, E_REF, E_NAME, E_NULL)}


class Rng:
    __slots__ = ('sh', 'r1', 'c1', 'r2', 'c2')

    def __init__(self, sh, r1, c1, r2, c2):
        self.sh = sh
        self.r1 = r1
        self.c1 = c1
        self.r2 = r2
        self.c2 = c2


class FC:
    __slots__ = ('fn', 'st', 'val')

    def __init__(self, fn):
        self.fn = fn
        self.st = 0
        self.val = None


CELLS = {}
EPOCH = date(1899, 12, 30)


def cellval(sh, r, c):
    d = CELLS[sh]
    x = d.get((r, c))
    if x.__class__ is FC:
        if x.st == 2:
            return x.val
        if x.st == 1:
            return E_CIRC
        x.st = 1
        try:
            v = x.fn()
            if v.__class__ is Rng:
                v = cellval(v.sh, v.r1, v.c1)
        except RecursionError:
            raise
        except Exception:
            v = E_VAL
        if v is None:
            v = 0.0
        x.val = v
        x.st = 2
        return v
    return x


def deref(v):
    if v.__class__ is Rng:
        return cellval(v.sh, v.r1, v.c1)
    return v


def rng_values(r):
    d = CELLS[r.sh]
    out = []
    for rr in range(r.r1, r.r2 + 1):
        for cc in range(r.c1, r.c2 + 1):
            x = d.get((rr, cc))
            if x.__class__ is FC:
                x = cellval(r.sh, rr, cc)
            out.append(x)
    return out


def rng_cells(r):
    # yields (value) for each cell in row-major order
    return rng_values(r)


def tonum(v):
    c = v.__class__
    if c is float:
        return v
    if v is None:
        return 0.0
    if c is bool:
        return 1.0 if v else 0.0
    if c is str:
        p = parse_num(v)
        return E_VAL if p is None else p
    if c is Err:
        return v
    if c is int:
        return float(v)
    return E_VAL


def parse_num(s):
    t = s.strip()
    if not t:
        return None
    pct = False
    if t.endswith('%'):
        pct = True
        t = t[:-1].strip()
    if not re.fullmatch(r'[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?', t):
        if re.fullmatch(r'[+-]?\d{1,3}(,\d{3})+(\.\d*)?', t):
            t = t.replace(',', '')
        else:
            return None
    f = float(t)
    if pct:
        f /= 100.0
    return f


def tostr(v):
    c = v.__class__
    if c is str:
        return v
    if v is None:
        return ""
    if c is bool:
        return "TRUE" if v else "FALSE"
    if c is float:
        return num2str(v)
    if c is Err:
        return v
    if c is int:
        return str(v)
    return ""


def num2str(x):
    if x == int(x) and abs(x) < 1e15:
        return str(int(x))
    s = '%.15g' % x
    if 'e' in s:
        m, e = s.split('e')
        ev = int(e)
        return m + 'E' + ('+' if ev >= 0 else '-') + ('%02d' % abs(ev))
    return s


def tobool(v):
    c = v.__class__
    if c is bool:
        return v
    if c is float:
        return v != 0
    if c is int:
        return v != 0
    if v is None:
        return False
    if c is str:
        u = v.upper()
        if u == 'TRUE':
            return True
        if u == 'FALSE':
            return False
        p = parse_num(v)
        if p is None:
            return E_VAL
        return p != 0
    return v


def approx_eq(a, b):
    if a == b:
        return True
    return abs(a - b) <= 3.6e-15 * max(abs(a), abs(b))


def type_rank(v):
    c = v.__class__
    if c is float or c is int:
        return 0
    if c is str:
        return 1
    return 2


def cmp_vals(a, b):
    # returns -1,0,1 or Err
    if a.__class__ is Err:
        return a
    if b.__class__ is Err:
        return b
    if a is None:
        a = 0.0 if b.__class__ is float else ('' if b.__class__ is str else False)
    if b is None:
        b = 0.0 if a.__class__ is float else ('' if a.__class__ is str else False)
    ra, rb = type_rank(a), type_rank(b)
    if ra != rb:
        return -1 if ra < rb else 1
    if ra == 0:
        if approx_eq(a, b):
            return 0
        return -1 if a < b else 1
    if ra == 1:
        x, y = a.lower(), b.lower()
        return 0 if x == y else (-1 if x < y else 1)
    x, y = int(a), int(b)
    return 0 if x == y else (-1 if x < y else 1)


def eq_key(v):
    if v.__class__ is str:
        return v.lower()
    return v


# ---------- criteria ----------
def wild_re(p):
    out = []
    i = 0
    while i < len(p):
        ch = p[i]
        if ch == '~' and i + 1 < len(p) and p[i + 1] in '*?~':
            out.append(re.escape(p[i + 1]))
            i += 2
            continue
        if ch == '*':
            out.append('.*')
        elif ch == '?':
            out.append('.')
        else:
            out.append(re.escape(ch))
        i += 1
    return re.compile('^' + ''.join(out) + '$', re.I | re.S)


_wcache = {}


def get_wild(p):
    r = _wcache.get(p)
    if r is None:
        r = wild_re(p)
        _wcache[p] = r
    return r


def make_matcher(crit):
    """returns predicate on cell value"""
    if crit.__class__ is Err:
        return lambda v: False
    if crit.__class__ is float or crit.__class__ is int:
        x = float(crit)
        return lambda v: v.__class__ is float and approx_eq(v, x)
    if crit.__class__ is bool:
        return lambda v: v.__class__ is bool and v == crit
    if crit is None:
        crit = ''
    s = crit
    op = '='
    for o in ('<=', '>=', '<>', '<', '>', '='):
        if s.startswith(o):
            op = o
            s = s[len(o):]
            break
    num = parse_num(s) if s.strip() != '' else None
    if num is not None and not (s.strip().upper() in ('TRUE', 'FALSE')):
        x = num
        if op == '=':
            return lambda v: v.__class__ is float and approx_eq(v, x)
        if op == '<>':
            return lambda v: not (v.__class__ is float and approx_eq(v, x))
        def f(v, op=op, x=x):
            if v.__class__ is not float:
                return False
            c = 0 if approx_eq(v, x) else (-1 if v < x else 1)
            return {'<': c < 0, '>': c > 0, '<=': c <= 0, '>=': c >= 0}[op]
        return f
    if s.upper() in ('TRUE', 'FALSE') and op in ('=', '<>'):
        b = s.upper() == 'TRUE'
        if op == '=':
            return lambda v: v.__class__ is bool and v == b
        return lambda v: not (v.__class__ is bool and v == b)
    if s == '':
        if op == '=':
