def _vlookup_common(args, horiz):
    needle = scal(args, 0)
    if needle.__class__ is Err:
        return needle
    tbl = args[1]()
    idx = scal(args, 2)
    if idx.__class__ is Err:
        return idx
    idx = tonum(idx)
    if idx.__class__ is Err:
        return idx
    approx = True
    if len(args) > 3:
        ap = scal(args, 3)
        if ap.__class__ is Err:
            return ap
        approx = tobool(ap)
        if approx.__class__ is Err:
            return approx
    if tbl.__class__ is not Rng:
        return E_VAL
    h = tbl.r2 - tbl.r1 + 1
    w = tbl.c2 - tbl.c1 + 1
    k = int(idx)
    if horiz:
        if k < 1 or k > h:
            return E_REF
        keyvals = rng_values(Rng(tbl.sh, tbl.r1, tbl.c1, tbl.r1, tbl.c2))
    else:
        if k < 1 or k > w:
            return E_REF
        keyvals = rng_values(Rng(tbl.sh, tbl.r1, tbl.c1, tbl.r2, tbl.c1))
    if approx:
        if needle is None:
            return E_NA
        i = _approx_index(needle, keyvals)
        if i < 0:
            return E_NA
    else:
        i = _exact_index(needle, keyvals)
        if i < 0:
            return E_NA
    if horiz:
        r = tbl.r1 + k - 1
        cc = tbl.c1 + i
        return Rng(tbl.sh, r, cc, r, cc)
    r = tbl.r1 + i
    cc = tbl.c1 + k - 1
