@fn('MATCH')
def f_match(args):
    needle = scal(args, 0)
    if needle.__class__ is Err:
        return needle
    arr = args[1]()
    mt = 1.0
    if len(args) > 2:
        mt = tonum(scal(args, 2))
        if mt.__class__ is Err:
            return mt
    if arr.__class__ is not Rng:
        return E_VAL
    vals = rng_values(arr)
    if needle is None:
        needle = 0.0
    if mt == 0:
        i = _exact_index(needle, vals)
    elif mt > 0:
        i = _approx_index(needle, vals)
    else:
        # smallest value >= needle, descending
        i = -1
        lo, hi = 0, len(vals) - 1
        best = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            c = cmp_vals(vals[mid], needle)
            if c.__class__ is Err:
                hi = mid - 1
                continue
            if c >= 0:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        i = best
    if i < 0:
        return E_NA
    return float(i + 1)


