    sm = 1.0
    if len(args) > 5:
        sm = tonum(scal(args, 5))
        if sm.__class__ is Err:
            return sm
    lv = rng_values(la)
    n = len(lv)
    order = range(n) if sm >= 0 else range(n - 1, -1, -1)
    idx = -1
    if mm == 0:
        for i in order:
            if _eqv(lv[i], needle):
                idx = i
                break
    elif mm == 2:
        rx = get_wild(tostr(needle))
        for i in order:
            v = lv[i]
            if v.__class__ is str and rx.match(v):
                idx = i
