def _eqv(a, b):
    if a is None:
        return False
    if a.__class__ is Err or b.__class__ is Err:
        return False
    if a.__class__ is str and b.__class__ is str:
        return a.lower() == b.lower()
    if type_rank(a) != type_rank(b):
        return False
    if a.__class__ is float:
        return approx_eq(a, b)
    return a == b


