@fn('DATE')
def f_date(args):
    y = tonum(scal(args, 0))
    m = tonum(scal(args, 1))
    d = tonum(scal(args, 2))
    for x in (y, m, d):
        if x.__class__ is Err:
            return x
    y = int(y)
    m = int(m)
    d = int(d)
    if 0 <= y < 1900:
        y += 1900
    if y < 0 or y > 9999:
        return E_NUM
    y += (m - 1) // 12
    m = (m - 1) % 12 + 1
    try:
        base = date(y, m, 1)
    except ValueError:
        return E_NUM
    res = base + timedelta(days=d - 1)
    return serial_of(res)


