@fn('DATEDIF')
def f_datedif(args):
    s = tonum(scal(args, 0))
    if s.__class__ is Err:
        return s
    e = tonum(scal(args, 1))
    if e.__class__ is Err:
        return e
    unit = scal(args, 2)
    if unit.__class__ is Err:
        return unit
    unit = tostr(unit).upper()
    if s > e:
        return E_NUM
    d1 = to_date(s)
    d2 = to_date(e)
    if unit == 'Y':
        y = d2.year - d1.year
        if (d2.month, d2.day) < (d1.month, d1.day):
            y -= 1
        return float(y)
    if unit == 'M':
        m = (d2.year - d1.year) * 12 + (d2.month - d1.month)
        if d2.day < d1.day:
            m -= 1
        return float(m)
    if unit == 'D':
        return float((d2 - d1).days)
    if unit == 'MD':
        if d2.day >= d1.day:
            return float(d2.day - d1.day)
        pm_y, pm_m = (d2.year, d2.month - 1) if d2.month > 1 else (d2.year - 1, 12)
        return float(days_in_month(pm_y, pm_m) - d1.day + d2.day)
    if unit == 'YM':
        m = (d2.month - d1.month)
        if d2.day < d1.day:
            m -= 1
        return float(m % 12)
    if unit == 'YD':
        y = d2.year
        try:
            s2 = date(y, d1.month, d1.day)
        except ValueError:
            s2 = date(y, d1.month, 28)
        if s2 > d2:
            try:
                s2 = date(y - 1, d1.month, d1.day)
            except ValueError:
                s2 = date(y - 1, d1.month, 28)
        return float((d2 - s2).days)
    return E_NUM


