# ---------- lookup ----------
def _lk_match(needle, v, wild):
    if needle.__class__ is str and wild:
        rx = get_wild(needle)
        return v.__class__ is str and rx.match(v) is not None
    return cmp_vals(v, needle) == 0 and v.__class__ is needle.__class__ or (
        needle.__class__ in (float, int) and v.__class__ is float and approx_eq(v, float(needle)))


def _exact_index(needle, vals, wild=True):
    if needle.__class__ is str and wild and ('*' in needle or '?' in needle or '~' in needle):
        for i, v in enumerate(vals):
            if _lk_match(needle, v, True):
                return i
        return -1
    if needle.__class__ is float:
        for i, v in enumerate(vals):
            if v.__class__ is float and approx_eq(v, needle):
                return i
        return -1
    if needle.__class__ is str:
        nl = needle.lower()
        for i, v in enumerate(vals):
            if v.__class__ is str and v.lower() == nl:
                return i
        return -1
    if needle.__class__ is bool:
        for i, v in enumerate(vals):
            if v.__class__ is bool and v == needle:
                return i
        return -1
    return -1


def _approx_index(needle, vals):
    # largest value <= needle, ascending assumed; binary search
    best = -1
    lo, hi = 0, len(vals) - 1
    # linear fallback semantics: binary search like Excel
    while lo <= hi:
        mid = (lo + hi) // 2
        v = vals[mid]
        c = cmp_vals(v, needle)
        if c is None or c.__class__ is Err:
            hi = mid - 1
            continue
        if v is None:
            c = 1
        if c <= 0:
            best = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return best


def _lookup_args(args):
    return None


def _vlookup_common(args, horiz):
    needle = scal(args, 0)
    if needle.__class__ is Err:
        return needle
    tbl = args[1]()
    idx = scal(args, 2)
    if idx.__class__ is Err:
        return idx
    idx = tonum(idx)
    if idx.__class__ is Err:
        return idx
    approx = True
    if len(args) > 3:
        ap = scal(args, 3)
        if ap.__class__ is Err:
            return ap
        approx = tobool(ap)
        if approx.__class__ is Err:
            return approx
    if tbl.__class__ is not Rng:
        return E_VAL
    h = tbl.r2 - tbl.r1 + 1
    w = tbl.c2 - tbl.c1 + 1
    k = int(idx)
    if horiz:
        if k < 1 or k > h:
            return E_REF
        keyvals = rng_values(Rng(tbl.sh, tbl.r1, tbl.c1, tbl.r1, tbl.c2))
    else:
        if k < 1 or k > w:
            return E_REF
        keyvals = rng_values(Rng(tbl.sh, tbl.r1, tbl.c1, tbl.r2, tbl.c1))
    if approx:
        if needle is None:
            return E_NA
        i = _approx_index(needle, keyvals)
        if i < 0:
            return E_NA
    else:
        i = _exact_index(needle, keyvals)
        if i < 0:
            return E_NA
    if horiz:
        r = tbl.r1 + k - 1
        cc = tbl.c1 + i
        return Rng(tbl.sh, r, cc, r, cc)
    r = tbl.r1 + i
    cc = tbl.c1 + k - 1
    return Rng(tbl.sh, r, cc, r, cc)


@fn('VLOOKUP')
def f_vlookup(args):
    r = _vlookup_common(args, False)
    return deref(r) if r.__class__ is Rng else r


@fn('HLOOKUP')
def f_hlookup(args):
    r = _vlookup_common(args, True)
    return deref(r) if r.__class__ is Rng else r


@fn('MATCH')
def f_match(args):
    needle = scal(args, 0)
    if needle.__class__ is Err:
        return needle
    arr = args[1]()
    mt = 1.0
    if len(args) > 2:
        mt = tonum(scal(args, 2))
        if mt.__class__ is Err:
            return mt
    if arr.__class__ is not Rng:
        return E_VAL
    vals = rng_values(arr)
    if needle is None:
        needle = 0.0
    if mt == 0:
        i = _exact_index(needle, vals)
    elif mt > 0:
        i = _approx_index(needle, vals)
    else:
        # smallest value >= needle, descending
        i = -1
        lo, hi = 0, len(vals) - 1
        best = -1
        while lo <= hi:
            mid = (lo + hi) // 2
            c = cmp_vals(vals[mid], needle)
            if c.__class__ is Err:
                hi = mid - 1
                continue
            if c >= 0:
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        i = best
    if i < 0:
        return E_NA
    return float(i + 1)


@fn('INDEX')
def f_index(args):
    arr = args[0]()
    if arr.__class__ is not Rng:
        return E_VAL
    r = scal(args, 1)
    c = scal(args, 2) if len(args) > 2 else None
    if r.__class__ is Err:
        return r
    h = arr.r2 - arr.r1 + 1
    w = arr.c2 - arr.c1 + 1
    ri = int(tonum(r)) if r is not None else 0
    ci = int(tonum(c)) if c is not None else 0
    if c is None and len(args) <= 2:
        if h == 1 and w > 1:
            ci, ri = ri, 1
        elif w == 1:
            ci = 1
    if ri == 0 and ci == 0 and h == 1 and w == 1:
        ri = ci = 1
    if ri < 0 or ci < 0:
        return E_VAL
    if ri == 0:
        ri = 1
    if ci == 0:
        ci = 1
    if ri > h or ci > w:
        return E_REF
    rr = arr.r1 + ri - 1
    cc = arr.c1 + ci - 1
    return Rng(arr.sh, rr, cc, rr, cc)


@fn('XLOOKUP')
def f_xlookup(args):
    needle = scal(args, 0)
    if needle.__class__ is Err:
        return needle
    la = args[1]()
    ra = args[2]()
    if la.__class__ is not Rng or ra.__class__ is not Rng:
        return E_VAL
    nf = args[3]() if len(args) > 3 else None
    mm = 0.0
    if len(args) > 4:
        mm = tonum(scal(args, 4))
        if mm.__class__ is Err:
            return mm
    sm = 1.0
    if len(args) > 5:
        sm = tonum(scal(args, 5))
        if sm.__class__ is Err:
            return sm
    lv = rng_values(la)
    n = len(lv)
    order = range(n) if sm >= 0 else range(n - 1, -1, -1)
    idx = -1
    if mm == 0:
        for i in order:
            if _eqv(lv[i], needle):
                idx = i
                break
    elif mm == 2:
        rx = get_wild(tostr(needle))
        for i in order:
            v = lv[i]
            if v.__class__ is str and rx.match(v):
                idx = i
                break
            if v.__class__ is float and needle.__class__ is float and approx_eq(v, needle):
                idx = i
                break
    else:
        # -1: exact or next smaller; 1: exact or next larger
        best = None
        bi = -1
        for i in order:
            v = lv[i]
            if v is None or v.__class__ is Err:
                continue
            if _eqv(v, needle):
                bi = i
                best = None
                break
            c = cmp_vals(v, needle)
            if c.__class__ is Err or type_rank(v) != type_rank(needle):
                continue
            if mm == -1 and c < 0:
                if best is None or cmp_vals(v, best) > 0:
                    best = v
                    bi = i
            if mm == 1 and c > 0:
                if best is None or cmp_vals(v, best) < 0:
                    best = v
                    bi = i
        idx = bi
    if idx < 0:
        if nf is None:
            return E_NA
        return nf
    rv = rng_values(ra)
    if idx >= len(rv):
        return E_REF
    v = rv[idx]
    return 0.0 if v is None else v


def _eqv(a, b):
    if a is None:
        return False
    if a.__class__ is Err or b.__class__ is Err:
        return False
    if a.__class__ is str and b.__class__ is str:
        return a.lower() == b.lower()
    if type_rank(a) != type_rank(b):
        return False
    if a.__class__ is float:
        return approx_eq(a, b)
    return a == b


# ---------- date functions ----------
@fn('DATE')
def f_date(args):
    y = tonum(scal(args, 0))
    m = tonum(scal(args, 1))
    d = tonum(scal(args, 2))
    for x in (y, m, d):
        if x.__class__ is Err:
            return x
    y = int(y)
    m = int(m)
    d = int(d)
    if 0 <= y < 1900:
        y += 1900
    if y < 0 or y > 9999:
        return E_NUM
    y += (m - 1) // 12
    m = (m - 1) % 12 + 1
    try:
        base = date(y, m, 1)
    except ValueError:
        return E_NUM
    res = base + timedelta(days=d - 1)
    return serial_of(res)


def _sd(args, i):
    v = tonum(scal(args, i))
    if v.__class__ is Err:
        return v
    if v < 0:
        return E_NUM
    return to_date(v)


@fn('YEAR')
def f_year(args):
