    return serial_of(date(d.year, d.month, days_in_month(d.year, d.month)))


@fn('DATEDIF')
def f_datedif(args):
    s = tonum(scal(args, 0))
    if s.__class__ is Err:
        return s
    e = tonum(scal(args, 1))
    if e.__class__ is Err:
        return e
    unit = scal(args, 2)
    if unit.__class__ is Err:
        return unit
    unit = tostr(unit).upper()
    if s > e:
        return E_NUM
    d1 = to_date(s)
    d2 = to_date(e)
    if unit == 'Y':
        y = d2.year - d1.year
        if (d2.month, d2.day) < (d1.month, d1.day):
            y -= 1
        return float(y)
    if unit == 'M':
        m = (d2.year - d1.year) * 12 + (d2.month - d1.month)
        if d2.day < d1.day:
            m -= 1
        return float(m)
    if unit == 'D':
        return float((d2 - d1).days)
    if unit == 'MD':
        if d2.day >= d1.day:
            return float(d2.day - d1.day)
        pm_y, pm_m = (d2.year, d2.month - 1) if d2.month > 1 else (d2.year - 1, 12)
        return float(days_in_month(pm_y, pm_m) - d1.day + d2.day)
    if unit == 'YM':
        m = (d2.month - d1.month)
        if d2.day < d1.day:
            m -= 1
        return float(m % 12)
    if unit == 'YD':
        y = d2.year
        try:
            s2 = date(y, d1.month, d1.day)
        except ValueError:
            s2 = date(y, d1.month, 28)
        if s2 > d2:
            try:
                s2 = date(y - 1, d1.month, d1.day)
            except ValueError:
                s2 = date(y - 1, d1.month, 28)
        return float((d2 - s2).days)
    return E_NUM


# ---------- driver ----------
def load_book(path):
    z = zipfile.ZipFile(path)
    names = set(z.namelist())
    wb = ET.fromstring(z.read("xl/workbook.xml"))
    rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    relmap = {r.get("Id"): r.get("Target") for r in rels}
    ss = []
    if "xl/sharedStrings.xml" in names:
        for si in ET.fromstring(z.read("xl/sharedStrings.xml")).findall(M + "si"):
            t = si.find(M + "t")
            if t is not None:
                ss.append(t.text or "")
            else:
                ss.append("".join((r.findtext(M + "t") or "") for r in si.findall(M + "r")))
    sheets = []
    for s in wb.find(M + "sheets"):
        target = relmap[s.get(R_ID)]
        p = target.lstrip("/") if target.startswith("/") else "xl/" + target
        sheets.append((s.get("name"), p))
    raw = {}
    forms = []  # (sheetname, r, c, formula text)
    for name, p in sheets:
        root = ET.fromstring(z.read(p))
        cells = {}
        CELLS[name] = cells
        for c in root.iter(M + "c"):
            ref = c.get("r")
            m = re.fullmatch(r'([A-Z]+)(\d+)', ref)
            key = (int(m.group(2)), col2n(m.group(1)))
            t = c.get("t", "n")
            f = c.find(M + "f")
            v = c.find(M + "v")
            vt = v.text if v is not None else None
            if f is not None:
                forms.append((name, key, f.text or ""))
                continue
            if vt is None:
                if t == "inlineStr":
                    is_ = c.find(M + "is")
                    if is_ is not None:
                        cells[key] = "".join(x.text or "" for x in is_.iter(M + "t"))
                continue
            if t == "s":
                cells[key] = ss[int(vt)]
            elif t in ("str", "inlineStr"):
                cells[key] = vt
            elif t == "b":
                cells[key] = vt == "1"
            elif t == "e":
                cells[key] = ERRMAP.get(vt, E_VAL)
            else:
                cells[key] = float(vt)
    return [s[0] for s in sheets], forms


def run(inp, outp):
    names, forms = load_book(inp)
    for name, key, text in forms:
        p = Parser(tokenize(text), name)
        try:
            fnc = p.parse()
        except Exception:
            fnc = (lambda: E_NAME)
        CELLS[name][key] = FC(fnc)
    out = {}
    for name, key, text in forms:
        pass
    for name, key, text in forms:
        v = cellval(name, key[0], key[1])
        out.setdefault(name, {})
        ref = colname(key[1]) + str(key[0])
        if v.__class__ is bool:
            e = {"t": "b", "v": v}
        elif v.__class__ is float or v.__class__ is int:
            if math.isnan(v) or math.isinf(v):
                e = {"t": "e", "v": "#NUM!"}
            else:
                e = {"t": "n", "v": float(v)}
        elif v.__class__ is str:
            e = {"t": "s", "v": v}
        elif v.__class__ is Err:
            e = {"t": "e", "v": v.c}
        else:
            e = {"t": "n", "v": 0.0}
        out[name][ref] = e
    with open(outp, "w") as fh:
        json.dump(out, fh)


def colname(n):
    s = ''
    while n:
        n, r = divmod(n - 1, 26)
        s = chr(65 + r) + s
    return s


def main(argv):
    inp = outp = None
    i = 0
    while i < len(argv):
        if argv[i] == '--in':
            inp = argv[i + 1]
            i += 2
        elif argv[i] == '--out':
            outp = argv[i + 1]
            i += 2
        else:
            i += 1
    if inp is None or outp is None:
        print("usage: calc eval --in book.xlsx --out values.json", file=sys.stderr)
        return 2
    sys.setrecursionlimit(1000000)
    threading.stack_size(512 * 1024 * 1024)
    res = [0]

    def target():
        try:
            run(inp, outp)
        except Exception as ex:
            import traceback
            traceback.print_exc()
            res[0] = 1
    t = threading.Thread(target=target)
    t.start()
    t.join()
    return res[0]


if __name__ == '__main__':
    args = sys.argv[1:]
    if args and args[0] == 'eval':
        args = args[1:]
    sys.exit(main(args))
